import{z as l,x as A,o as r,c as o,q as i,j as s,D as t,d as e,s as m,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const Q=JSON.parse('{"title":"风险中性测度","description":"","frontmatter":{"title":"风险中性测度","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/risk-neutral-measure.md","filePath":"quant/risk-neutral-measure.md","lastUpdated":1791413859000}'),d={name:"quant/risk-neutral-measure.md"};function h(u,a,p,D,c,C){const B=A("Mermaid");return r(),o("div",null,[a[2]||(a[2]=i('<h1 id="风险中性测度" tabindex="-1">风险中性测度 <a class="header-anchor" href="#风险中性测度" aria-label="Permalink to &quot;风险中性测度&quot;">​</a></h1><div class="epigraph"><p>无套利当且仅当存在等价测度 $Q$，使贴现资产价格为 $Q$-鞅。价格是 $Q$ 下贴现期望，不是 $P$ 下用 $\\mu$ 折现。</p><footer>—— 据 Harrison and Pliska, Stochastic Processes and their Applications, 1981；Shreve, Stochastic Calculus for Finance II, 2004, 第 5 章整理</footer></div><p>上一课<a href="/quant/girsanov-measure">Girsanov 测度变换</a>给出任意漂移平移。缺口是选出那一个 \\(\\theta\\)：让贴现标的 \\(S/B\\) 成为鞅。这不是投资者风险中性的心理学假设，而是无套利的概率翻译。本课只钉这条等价，不讨论唯一性——唯一性是下一课完备市场。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>真实测度 \\(P\\) 下 \\(\\mathrm d S=\\mu S\\,\\mathrm d t+\\sigma S\\,\\mathrm d W\\)，\\(\\mu\\) 含风险溢价，不可直接拿来贴现取期望：不同资产 \\(\\mu\\) 不同，组合的折现率没有单一数字。缺口是换到 \\(Q\\sim P\\)，使 \\(\\mathrm d S=r S\\,\\mathrm d t+\\sigma S\\,\\mathrm d W^Q\\)（利率先当常数）。此时 \\(\\mathrm e^{-rt}S_t\\) 为 \\(Q\\)-鞅，未定权益 \\(H\\) 的价格为 \\(\\mathrm e^{-rT}\\mathbb E_Q[H]\\)。没有 \\(Q\\)，复制价格和对冲比率都还没有概率表达式。</p><p><span class="marginnote">术语翻译：鞅就是「公平赌局」——已知今天全部信息后，明天的期望值恰好等于今天的值，不多不少。「贴现价格是 \\(Q\\)-鞅」= 在 \\(Q\\) 这套概率权重下，持有资产扣掉利息后平均不赚不赔；定价公式就是把未来支付按这套公平赔率取平均。</span></p><p>Harrison–Kreps / Harrison–Pliska 把「无套利」与「存在等价鞅测度」焊在一起。本课用这条第一基本定理的可用形式，不把离散模型的证明重写。</p><h3 id="风险中性不是「投资者不在乎风险」" tabindex="-1">风险中性不是「投资者不在乎风险」 <a class="header-anchor" href="#风险中性不是「投资者不在乎风险」" aria-label="Permalink to &quot;风险中性不是「投资者不在乎风险」&quot;">​</a></h3><p>\\(Q\\) 下超额回报为零，是因为已经把风险溢价吸进测度。\\(P\\) 下投资者仍可以厌恶风险，\\(\\mu\\gt r\\) 完全合法。把 \\(Q\\) 读成偏好假设，后面不全市场里「许多 \\(Q\\)」会变成许多偏好，对象错位。\\(Q\\) 是定价测度，不是描述测度。</p><p><span class="marginnote">贴现因子 \\(B_t=\\mathrm e^{rt}\\) 是本课的计价物。随机利率时要换成储蓄账户 \\(\\exp(\\int r)\\)，预告在<a href="/quant/stochastic-rate-preview">利率不是常数</a>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>市场含无风险 \\(B\\) 与 GBM 标的 \\(S\\)。取 \\(\\theta=(\\mu-r)/\\sigma\\)（\\(\\sigma\\neq 0\\)），Girsanov 给出 \\(Q\\)。则</p> \\[\\mathrm d S_t=r S_t\\,\\mathrm d t+\\sigma S_t\\,\\mathrm d W^Q_t, \\]<p>且 \\(V_t=\\mathrm e^{-r(T-t)}\\mathbb E_Q[H\\mid\\mathcal F_t]\\) 是贴现鞅的可料表示候选。欧式看涨 \\(H=(S_T-K)^+\\) 的价格因此是 \\(Q\\) 下对数正态期望——闭式留给 Black 公式课。本课只锁定：\\(P\\) 中的 \\(\\mu\\) 退出定价公式。</p><p><span class="marginnote">数字实例：取 \\(\\mu=8\\%\\)、\\(r=3\\%\\)、\\(\\sigma=20\\%\\)，则 \\(\\theta=(8\\%-3\\%)/20\\%=0.25\\)。Girsanov 用这 0.25 重新分配路径概率权重：大涨的路径调轻、大跌的调重，恰好把平均漂移从 8% 压到 3%。波动率 \\(\\sigma\\) 不受影响——换测度不改变路径抖动的幅度。</span></p><p>复制：若 \\(H\\) 可写成 \\(\\int\\Delta\\,\\mathrm d S\\) 加货币市场，则该 \\(\\Delta\\) 的损益在 \\(Q\\) 下为鞅，初值等于上述期望。对冲细节是<a href="/quant/replicating-delta">复制与 delta</a>。</p>',16)),(r(),s(n,null,{default:t(()=>[m(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%89%A9%E7%90%86%E6%B5%8B%E5%BA%A6%EF%BC%9A%E6%BC%82%E7%A7%BB%20mu%22%5D%20--%3E%20THETA%5B%22theta%20%E7%AD%89%E4%BA%8E%20mu%20%E5%87%8F%20r%20%E5%86%8D%E9%99%A4%20sigma%22%5D%0A%20%20THETA%20--%3E%20Q%5B%22%E7%AD%89%E4%BB%B7%E9%9E%85%E6%B5%8B%E5%BA%A6%22%5D%0A%20%20Q%20--%3E%20PRICE%5B%22%E4%BB%B7%E6%A0%BC%E7%AD%89%E4%BA%8E%20Q%20%E4%B8%8B%E8%B4%B4%E7%8E%B0%E6%9C%9F%E6%9C%9B%22%5D%0A%20%20PRICE%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E5%94%AF%E4%B8%80%E6%80%A7%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"无套利禁止「零投入、非负收益且正概率严格为正」。若贴现 \\(S\\) 在某等价测度下为鞅，则任何可积可料策略的贴现价值也是局部鞅，取期望得不到严格优势——存在 \\(Q\\) 推出无套利（技术条件上要可容许策略）。反过来，有套利则没有任何 \\(Q\\) 能让所有贴现资产走平。这是第一基本定理的方向。\\(\\theta=(\\mu-r)/\\sigma\\) 把每个噪声源上的超额回报标准化，正是 Girsanov 的旋钮对准「取消 \\(\\mu-r\\)」。",-1)),a[5]||(a[5]=E("p",null,"\\(Q\\) 与 \\(P\\) 在零集上一致，故 \\(S\\gt 0\\)、\\(T\\lt \\infty\\) 等 \\(P\\)-a.s. 事件在定价里原样保留。改变的只是路径权重，不是支撑集。",-1)),(r(),s(n,null,{default:t(()=>[m(B,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E5%81%87%E8%AE%BE%E5%AD%98%E5%9C%A8%20Q%EF%BC%9A%E8%B4%B4%E7%8E%B0%20S%20%E4%B8%BA%E9%9E%85%22%5D%20--%3E%20B%5B%22%E4%BB%BB%E4%BD%95%E7%AD%96%E7%95%A5%E7%9A%84%E8%B4%B4%E7%8E%B0%E4%BB%B7%E5%80%BC%E4%B9%9F%E6%98%AF%E9%9E%85%22%5D%0A%20%20B%20--%3E%20C%5B%22%E9%9B%B6%E6%88%90%E6%9C%AC%E7%AD%96%E7%95%A5%E7%9A%84%E6%9C%9F%E6%9C%9B%E6%94%B6%E7%9B%8A%E4%B8%BA%200%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%97%A0%E5%A5%97%E5%88%A9%E6%88%90%E7%AB%8B%22%5D%0A%20%20E%5B%22%E8%8B%A5%E6%9C%89%E5%A5%97%E5%88%A9%EF%BC%9A%E9%9B%B6%E6%8A%95%E5%85%A5%E3%80%81%E7%A8%B3%E8%B5%9A%E4%B8%8D%E8%B5%94%22%5D%20--%3E%20F%5B%22%E8%B4%B4%E7%8E%B0%E4%BB%B7%E5%80%BC%E5%9C%A8%E4%BB%BB%E4%BD%95%20Q%20%E4%B8%8B%E9%83%BD%E6%9C%89%E4%B8%A5%E6%A0%BC%E6%AD%A3%E6%BC%82%E7%A7%BB%22%5D%0A%20%20F%20--%3E%20G%5B%22%E8%BF%99%E6%A0%B7%E7%9A%84%20Q%20%E4%B8%8D%E5%8F%AF%E8%83%BD%E5%AD%98%E5%9C%A8%22%5D%0A%20%20D%20-.%20%22%E4%B8%A4%E4%B8%AA%E6%96%B9%E5%90%91%E5%90%88%E8%B5%B7%E6%9D%A5%E5%8D%B3%E7%AC%AC%E4%B8%80%E5%9F%BA%E6%9C%AC%E5%AE%9A%E7%90%86%22%20.-%20G%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课假设常数 \\(r\\)、一个布朗、\\(\\sigma\\neq 0\\)，以便 \\(Q\\) 立刻存在。多资产、随机 \\(r\\)、跳，会让「存在」与「唯一」分开。后课默认：欧式未定权益先写成 \\(\\mathrm e^{-rT}\\mathbb E_Q[H]\\)；\\(P\\) 下的 \\(\\mu\\) 不进价格。下一课<a href="/quant/complete-unique-measure">完备市场与唯一测度</a>问这个 \\(Q\\) 是不是仅有的一个。</p><p><span class="marginnote">常见误区：拿 \\(Q\\) 下的分布去算「明年股票上涨的概率」。\\(Q\\) 是让价格无套利的记账权重，不是预测；要回答涨的概率，必须回到 \\(P\\) 并额外假设风险溢价——这正是定价与风险管理用两套测度的原因。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无套利 \\(\\Leftrightarrow\\) 存在等价测度使贴现资产为鞅。</li><li>风险中性是定价测度，不是偏好假设；\\(\\mu\\) 退出公式。</li><li>GBM 下 \\(\\theta=(\\mu-r)/\\sigma\\) 经 Girsanov 给出 \\(Q\\)。</li><li>价格 \\(=Q\\) 下贴现期望；波动率不变。</li><li>出处：Harrison–Pliska 1981；Shreve SDE II 第 5 章。</li></ul>',5))])}const S=l(d,[["render",h]]);export{Q as __pageData,S as default};
